80	func cmdQuery(dataFile string, argv []string, stdout, stderr io.Writer) int {
81		fs := newFlagSet("query", stderr)
82		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
83		id := fs.String("id", "", "要查询的包裹编号")
84		if ok, code := parseFlags(fs, argv, stdout, stderr, printQueryHelp); !ok {
85			return code
86		}
87	
88		cleanIDVal, err := cleanID("包裹编号", *id)
89		if err != nil {
90			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
91			return exitBusiness
92		}
93	
94		store, err := Open(dataFile)
95		if err != nil {
96			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
97			return exitBusiness
98		}
99		p, err := store.Query(cleanIDVal)
100		if err != nil {
101			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
102			return exitBusiness
103		}
104	
105		fmt.Fprintf(stdout, "包裹编号: %s\n当前站点: %s\n当前状态: %s\n", p.ID, p.Station, p.Status)
106		if f := store.ActiveFreeze(cleanIDVal); f != nil {
107			fmt.Fprintf(stdout, "当前未解除异常: 异常单号: %s    原因: %s    冻结时间: %s\n",
108				f.Incident, f.Reason, f.Time.Format(timeFmt))
109		}
110		fmt.Fprintf(stdout, "轨迹（按提交顺序，共 %d 条）:\n", len(p.Trail))
111		for i, e := range p.Trail {
112			switch e.Op {
113			case "退回":
114				fmt.Fprintf(stdout, "  %d. 操作: 退回    源站: %s    目的站: %s    退回请求号: %s    原交接请求号: %s    原因: %s    时间: %s\n",
115					i+1, e.From, e.Station, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
116			case "出站":
117				fmt.Fprintf(stdout, "  %d. 操作: 出站    站点: %s    批次号: %s    配送员: %s    时间: %s\n",
118					i+1, e.Station, e.Batch, e.Courier, e.Time.Format(timeFmt))
119			case "回执":
120				if e.Result == resultFailed {
121					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    原因: %s    请求号: %s    时间: %s\n",
122						i+1, e.Station, e.Batch, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
123				} else {
124					fmt.Fprintf(stdout, "  %d. 操作: 回执    站点: %s    批次号: %s    结果: %s    请求号: %s    时间: %s\n",
125						i+1, e.Station, e.Batch, e.Result, e.Request, e.Time.Format(timeFmt))
126				}
127			case "冻结":
128				fmt.Fprintf(stdout, "  %d. 操作: 冻结    站点: %s    异常单号: %s    原因: %s    时间: %s\n",
129					i+1, e.Station, e.Incident, e.Reason, e.Time.Format(timeFmt))
130			case "解除冻结":
131				fmt.Fprintf(stdout, "  %d. 操作: 解除冻结    站点: %s    异常单号: %s    解除请求号: %s    处理说明: %s    时间: %s\n",
132					i+1, e.Station, e.Incident, e.Request, e.Note, e.Time.Format(timeFmt))
133			default:
134				req := e.Request
135				if req == "" {
136					req = "-"
137				}
138				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
139					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
140			}
141		}
142		return exitOK
143	}
