270	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
271	// 不可为空、集合不可为空且编号不可重复。
272	func cleanParcelList(raw []string) ([]string, error) {
273		if len(raw) == 0 {
274			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
275		}
276		clean := make([]string, 0, len(raw))
277		seen := make(map[string]bool, len(raw))
278		for _, v := range raw {
279			id, err := cleanID("包裹编号", v)
280			if err != nil {
281				return nil, err
282			}
283			if seen[id] {
284				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
285			}
286			seen[id] = true
287			clean = append(clean, id)
288		}
289		return clean, nil
290	}
