349	func cmdReceipt(dataFile string, argv []string, stdout, stderr io.Writer) int {
350		fs := newFlagSet("receipt", stderr)
351		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
352		request := fs.String("request", "", "回执请求号（用于去重）")
353		batch := fs.String("batch", "", "配送批次号")
354		parcel := fs.String("parcel", "", "包裹编号")
355		result := fs.String("result", "", "回执结果：签收 或 失败")
356		reason := fs.String("reason", "", "失败原因（结果为失败时必填，签收时不可带）")
357		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptHelp); !ok {
358			return code
359		}
360	
361		cleanReq, err := cleanID("回执请求号", *request)
362		if err != nil {
363			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
364			return exitBusiness
365		}
366		cleanBatch, err := cleanID("批次号", *batch)
367		if err != nil {
368			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
369			return exitBusiness
370		}
371		cleanParcel, err := cleanID("包裹编号", *parcel)
372		if err != nil {
373			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
374			return exitBusiness
375		}
376		cleanResult, err := cleanID("回执结果", *result)
377		if err != nil {
378			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
379			return exitBusiness
380		}
381		if cleanResult != resultSigned && cleanResult != resultFailed {
382			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
383			return exitBusiness
384		}
385		cleanReason := strings.TrimSpace(*reason)
386		if cleanResult == resultFailed && cleanReason == "" {
387			fmt.Fprintf(stderr, "%s receipt: 结果为失败时原因不可为空或仅含空白\n", appName)
388			return exitBusiness
389		}
390		if cleanResult == resultSigned && cleanReason != "" {
391			fmt.Fprintf(stderr, "%s receipt: 结果为签收时不可带原因\n", appName)
392			return exitBusiness
393		}
394	
395		store, err := Open(dataFile)
396		if err != nil {
397			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
398			return exitBusiness
399		}
400		res, replayed, err := store.Receipt(cleanReq, cleanBatch, cleanParcel, cleanResult, cleanReason, now())
401		if err != nil {
402			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
403			return exitBusiness
404		}
405	
406		headline := "回执成功"
407		if replayed {
408			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
409		}
410		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
411			headline, res.Request, res.Batch, res.Parcel, res.Result)
412		if res.Result == resultFailed {
413			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
414		}
415		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
416		return exitOK
417	}
