473	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
474	func (s *Store) ActiveFreeze(id string) *FreezeResult {
475		p, ok := s.data.Parcels[id]
476		if !ok {
477			return nil
478		}
479		if no := activeFreeze(p); no != "" {
480			return s.data.Freezes[no]
481		}
482		return nil
483	}
