653	// Dispatch 提交一次配送批次出站。
654	//
655	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
656	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
657	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
658	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
659	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
660	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
661		if saved, ok := s.data.Batches[batch]; ok {
662			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
663				return saved, true, nil
664			}
665			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
666		}
667	
668		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
669		for _, id := range parcels {
670			p, ok := s.data.Parcels[id]
671			if !ok {
672				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
673			}
674			if p.Station != station {
675				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
676			}
677			if inc := activeFreeze(p); inc != "" {
678				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
679			}
680			if p.Status != statusInStation {
681				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
682			}
683		}
684	
685		res := &BatchResult{
686			Batch:    batch,
687			Station:  station,
688			Courier:  courier,
689			Parcels:  append([]string(nil), parcels...),
690			Time:     now,
691			Receipts: map[string]*ReceiptEntry{},
692		}
693		s.data.Batches[batch] = res
694	
695		// 记录旧值，落盘失败时整体回滚。
696		prev := make(map[string]struct {
697			status string
698			trail  []Event
699		}, len(parcels))
700		for _, id := range parcels {
701			p := s.data.Parcels[id]
702			prev[id] = struct {
703				status string
704				trail  []Event
705			}{p.Status, append([]Event(nil), p.Trail...)}
706			p.Status = statusDelivering // 站点不变，仍记出发站
707			p.Trail = append(p.Trail, Event{
708				Op:      "出站",
709				Station: station,
710				Batch:   batch,
711				Courier: courier,
712				Time:    now,
713			})
714		}
715	
716		if err := s.save(); err != nil {
717			delete(s.data.Batches, batch)
718			for id, old := range prev {
719				p := s.data.Parcels[id]
720				p.Status = old.status
721				p.Trail = old.trail
722			}
723			return nil, false, err
724		}
725		return res, false, nil
726	}
727	
728	// Receipt 提交一件包裹在某个配送批次下的回执。
729	//
730	// 首次回执：批次必须存在，包裹必须属于该批次、尚未在该批次回执，且当前仍在该批次
731	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
732	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
733	// 原因（失败时）、请求号和时间的回执记录；全部成员回执后批次自动完成。
734	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
735	// true，不重新检查当前状态，即使失败包裹已进入新批次；请求号相同但内容不同报冲突。
736	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
737	// 失败的首次回执不占用请求号。
738	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
739		if saved, ok := s.data.Receipts[request]; ok {
740			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
741				return saved, true, nil
742			}
743			return nil, false, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
744				request, saved.Batch, saved.Parcel, saved.Result)
745		}
746	
747		b, ok := s.data.Batches[batch]
748		if !ok {
749			return nil, false, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
750		}
751		member := false
752		for _, id := range b.Parcels {
753			if id == parcel {
754				member = true
755				break
756			}
757		}
758		if !member {
759			return nil, false, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
760		}
761		if _, done := b.Receipts[parcel]; done {
762			return nil, false, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能成功回执一次", parcel, batch)
763		}
764		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
765		if p.Status != statusDelivering || currentBatch(p) != batch {
766			return nil, false, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
767		}
768	
769		res = &ReceiptResult{
770			Request: request,
771			Batch:   batch,
772			Parcel:  parcel,
773			Result:  result,
774			Reason:  reason,
775			Time:    now,
776		}
777		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
778	
779		// 记录旧值，落盘失败时整体回滚。
780		oldStatus, oldStation := p.Status, p.Station
781		oldTrail := append([]Event(nil), p.Trail...)
782	
783		if result == resultSigned {
784			p.Status = statusSigned // 站点保留不变
785		} else {
786			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
787			p.Station = b.Station
788		}
789		p.Trail = append(p.Trail, Event{
790			Op:      "回执",
791			Station: p.Station,
792			Batch:   batch,
793			Result:  result,
794			Reason:  reason,
795			Request: request,
796			Time:    now,
797		})
798		b.Receipts[parcel] = entry
799		s.data.Receipts[request] = res
800	
801		if err := s.save(); err != nil {
802			delete(s.data.Receipts, request)
803			delete(b.Receipts, parcel)
804			p.Status, p.Station, p.Trail = oldStatus, oldStation, oldTrail
805			return nil, false, err
806		}
807		return res, false, nil
808	}
809	
810	// Freeze 对一件在站包裹登记异常冻结。
811	//
812	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
813	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
814	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
815	// 冻结只是管理记录，不移动实物、不算新流转。
816	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
817	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
818	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
819	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
820	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
821		if saved, ok := s.data.Freezes[incident]; ok {
822			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
823				return saved, true, nil
824			}
825			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
826				incident, saved.Parcel, saved.Station, saved.Reason)
827		}
828	
829		p, ok := s.data.Parcels[parcel]
830		if !ok {
831			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
832		}
833		if p.Station != station {
834			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
835		}
836		if p.Status != statusInStation {
837			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
838		}
839	
840		res = &FreezeResult{
841			Incident: incident,
842			Parcel:   parcel,
843			Station:  station,
844			Reason:   reason,
845			Time:     now,
846		}
847		s.data.Freezes[incident] = res
848	
849		// 记录旧值，落盘失败时整体回滚。
850		oldStatus := p.Status
851		oldTrail := append([]Event(nil), p.Trail...)
852		p.Status = statusFrozen // 站点不变
853		p.Trail = append(p.Trail, Event{
854			Op:       "冻结",
855			Station:  station,
856			Incident: incident,
857			Reason:   reason,
858			Time:     now,
859		})
860	
861		if err := s.save(); err != nil {
862			delete(s.data.Freezes, incident)
863			p.Status, p.Trail = oldStatus, oldTrail
864			return nil, false, err
865		}
866		return res, false, nil
867	}
868	
869	// Unfreeze 解除一件包裹当前的异常冻结。
870	//
871	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
872	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
873	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
874	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
875	// 解除只是管理记录，不移动实物、不算新流转。
876	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
877	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
878	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
879	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
880		if saved, ok := s.data.Unfreezes[request]; ok {
881			if saved.Incident == incident && saved.Note == note {
882				return saved, true, nil
883			}
884			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
885				request, saved.Incident, saved.Note)
886		}
887	
888		f, ok := s.data.Freezes[incident]
889		if !ok {
890			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
891		}
892		if f.ReleasedBy != "" {
893			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
894		}
895		p, ok := s.data.Parcels[f.Parcel]
896		if !ok {
897			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
898		}
899		if p.Status != statusFrozen || activeFreeze(p) != incident {
900			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
901				incident, f.Parcel, activeFreeze(p))
902		}
903	
904		res = &UnfreezeResult{
905			Request:  request,
906			Incident: incident,
907			Parcel:   f.Parcel,
908			Note:     note,
909			Time:     now,
910		}
911		s.data.Unfreezes[request] = res
912		f.ReleasedBy = request
913	
914		// 记录旧值，落盘失败时整体回滚。
915		oldStatus := p.Status
916		oldTrail := append([]Event(nil), p.Trail...)
917		p.Status = statusInStation // 在原站恢复在站，站点不变
918		p.Trail = append(p.Trail, Event{
919			Op:       "解除冻结",
920			Station:  f.Station,
921			Incident: incident,
922			Request:  request,
923			Note:     note,
924			Time:     now,
925		})
926	
927		if err := s.save(); err != nil {
928			delete(s.data.Unfreezes, request)
929			f.ReleasedBy = ""
930			p.Status, p.Trail = oldStatus, oldTrail
931			return nil, false, err
932		}
933		return res, false, nil
934	}
935	
936	// currentBatch 返回包裹当前配送中的批次号（最后一条出站记录的批次）；不在配送中返回空。
937	func currentBatch(p *Parcel) string {
938		for i := len(p.Trail) - 1; i >= 0; i-- {
939			if p.Trail[i].Op == "出站" {
940				return p.Trail[i].Batch
941			}
942		}
943		return ""
944	}
945	
946	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
947	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
948	func activeFreeze(p *Parcel) string {
949		if p.Status != statusFrozen {
950			return ""
951		}
952		for i := len(p.Trail) - 1; i >= 0; i-- {
953			if p.Trail[i].Op == "冻结" {
954				return p.Trail[i].Incident
955			}
956		}
957		return ""
958	}
959	
960	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执）。
961	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
962	func lastFlowEvent(trail []Event) Event {
963		for i := len(trail) - 1; i >= 0; i-- {
964			switch trail[i].Op {
965			case "冻结", "解除冻结":
966				continue
967			default:
968				return trail[i]
969			}
970		}
971		return Event{}
972	}
973	
974	// BatchQuery 返回一个配送批次的出站结果与逐件回执进度；批次不存在时报错。
975	func (s *Store) BatchQuery(batch string) (*BatchResult, error) {
976		b, ok := s.data.Batches[batch]
977		if !ok {
978			return nil, fmt.Errorf("批次 %q 不存在", batch)
979		}
980		return b, nil
981	}
982	
983	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
984	func sameSet(a, b []string) bool {
985		if len(a) != len(b) {
986			return false
987		}
988		x := append([]string(nil), a...)
989		y := append([]string(nil), b...)
990		sort.Strings(x)
991		sort.Strings(y)
992		for i := range x {
993			if x[i] != y[i] {
994				return false
995			}
996		}
997		return true
998	}
999	
1000	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
1001	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
1002	func (s *Store) save() error {
1003		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
1004			return fmt.Errorf("保存数据文件失败: %w", err)
1005		}
1006		buf, err := json.MarshalIndent(s.data, "", "  ")
1007		if err != nil {
1008			return fmt.Errorf("保存数据文件失败: %w", err)
1009		}
1010		buf = append(buf, '\n')
1011	
1012		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
1013		if err != nil {
1014			return fmt.Errorf("保存数据文件失败: %w", err)
1015		}
1016		tmpName := tmp.Name()
1017		cleanup := func() { _ = os.Remove(tmpName) }
1018	
1019		if _, err := tmp.Write(buf); err != nil {
1020			_ = tmp.Close()
1021			cleanup()
1022			return fmt.Errorf("保存数据文件失败: %w", err)
1023		}
1024		if err := tmp.Sync(); err != nil {
1025			_ = tmp.Close()
1026			cleanup()
1027			return fmt.Errorf("保存数据文件失败: %w", err)
1028		}
1029		if err := tmp.Close(); err != nil {
1030			cleanup()
1031			return fmt.Errorf("保存数据文件失败: %w", err)
1032		}
1033	
1034		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
1035		var check ledgerFile
1036		if err := json.Unmarshal(buf, &check); err != nil {
1037			cleanup()
1038			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
1039		}
1040	
1041		if err := os.Rename(tmpName, s.path); err != nil {
1042			cleanup()
1043			return fmt.Errorf("保存数据文件失败: %w", err)
1044		}
1045		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1046			_ = dir.Sync()
1047			_ = dir.Close()
1048		}
1049		return nil
1050	}
1051

