	// RC2 未被占用，P002 仍可正常回执。
	if _, _, code := runCLI(t, dbPath, "receipt", "--request", "RC2", "--batch", "B1", "--parcel", "P002", "--result", "签收"); code != 0 {
		t.Fatalf("RC2 应未被占用: %d", code)
	}
}

func TestCLIReceiptsFileProblems(t *testing.T) {
